// The sortie: mission state around the aircraft. Rings to thread, the timer,
// score, and which messages the HUD should be shouting right now.

import { MISSIONS, RING_SCORE, LANDING_BONUS, FUEL_BONUS_UNIT, TIME_LIMIT } from './config.js';
import { createAircraft, advance as advancePlane, EVENT_LANDED, EVENT_CRASH, EVENT_RING } from './aircraft.js';

export const SCREEN_TITLE = 'title';
export const SCREEN_BRIEF = 'brief';
export const SCREEN_PLAY = 'play';
export const SCREEN_PAUSED = 'paused';
export const SCREEN_END = 'end';

export function createWorld(seed, missionIndex = 0) {
  const mission = MISSIONS[missionIndex % MISSIONS.length];
  return {
    seed, missionIndex, mission,
    screen: SCREEN_TITLE,
    plane: createAircraft({ x: 0, z: 0, alt: 300, speed: 55, heading: 0 }),
    rings: [], ringIndex: 0,
    score: 0, time: TIME_LIMIT, elapsed: 0,
    messages: [], // {text, until}
    result: null, // {won, reason, score, stats}
    shake: 0,
  };
}

/** Begin a sortie: reset the plane at the mission start and arm the rings. */
export function startMission(world, missionIndex) {
  world.missionIndex = missionIndex;
  world.mission = MISSIONS[missionIndex % MISSIONS.length];
  world.plane = createAircraft({ x: -900, z: -2200, alt: 320, speed: 55, heading: 0 });
  world.rings = world.mission.rings.map((r) => ({ ...r, passed: false }));
  world.ringIndex = 0;
  world.score = 0;
  world.time = TIME_LIMIT;
  world.elapsed = 0;
  world.result = null;
  world.shake = 0;
  world.messages = [];
  world.screen = SCREEN_PLAY;
  say(world, `${world.mission.name}: fly through ${world.rings.length} rings, then land`, 5);
}

/** One fixed simulation step while playing. */
export function advance(world, input, dt) {
  if (world.screen !== SCREEN_PLAY) return;
  const events = [];
  advancePlane(world.plane, input, dt, events);

  world.elapsed += dt;
  world.time = Math.max(0, TIME_LIMIT - world.elapsed);
  world.shake = Math.max(0, world.shake - dt * 3);

  // rings
  const ring = world.rings[world.ringIndex];
  if (ring) {
    const dx = world.plane.x - ring.x, dz = world.plane.z - ring.z;
    const dAlt = world.plane.alt - ring.alt;
    if (Math.sqrt(dx * dx + dz * dz) < ring.r && Math.abs(dAlt) < ring.r * 0.8) {
      ring.passed = true;
      world.ringIndex += 1;
      world.score += RING_SCORE + Math.round(world.plane.fuel / 2);
      world.shake = 0.4;
      events.push({ type: EVENT_RING, index: world.ringIndex });
      say(world, world.ringIndex < world.rings.length
        ? `Ring ${world.ringIndex} of ${world.rings.length} — ${RING_SCORE} pts`
        : 'All rings cleared — return and land on runway 36', 4);
    }
  }

  for (const event of events) {
    if (event.type === EVENT_LANDED) finish(world, world.ringIndex >= world.rings.length, 'landed');
    if (event.type === EVENT_CRASH) finish(world, false, event.cause);
  }

  if (world.plane.fuel <= 0 && world.plane.speed < 25 && world.plane.alt - groundAt(world) < 400) {
    finish(world, false, 'ran out of fuel');
  }
  if (world.time <= 0) finish(world, false, 'out of time');
}

function groundAt(world) {
  // lazy import avoidance: terrain is small, read via world cache
  return world.groundProbe ? world.groundProbe(world.plane.x, world.plane.z) : 0;
}

/** Wire the terrain probe in once at boot so the world never imports terrain.js. */
export function setGroundProbe(world, fn) {
  world.groundProbe = fn;
}

function finish(world, won, reason) {
  if (world.result) return;
  const fuelBonus = won ? Math.round(world.plane.fuel * FUEL_BONUS_UNIT) : 0;
  const landBonus = won ? LANDING_BONUS : 0;
  world.result = {
    won, reason,
    score: world.score + fuelBonus + landBonus,
    fuelBonus, landBonus,
    rings: world.ringIndex, totalRings: world.rings.length,
    elapsed: Math.round(world.elapsed),
  };
  world.screen = SCREEN_END;
}

export function say(world, text, seconds) {
  world.messages = world.messages.filter((m) => m.until > world.elapsed);
  world.messages.push({ text, until: world.elapsed + seconds });
}

/** The message line the HUD draws, newest first. */
export function currentMessage(world) {
  for (let i = world.messages.length - 1; i >= 0; i--) {
    if (world.messages[i].until > world.elapsed) return world.messages[i].text;
  }
  return null;
}

/** Direction and distance to the current objective, for the HUD arrow. */
export function objective(world) {
  const ring = world.rings[world.ringIndex];
  if (ring) return { x: ring.x, z: ring.z, alt: ring.alt, label: 'RING', r: ring.r };
  const rw = { x: 0, z: 640, alt: 14 };
  return { ...rw, label: 'RUNWAY', r: 80 };
}
```

### game/src/aircraft.js (135 lines, 5382 bytes)

```js
// The aircraft: state, flight model, ground contact. One advance(step, input)
// integrates throttle, pitch, bank turns, lift, fuel and damage, and resolves
// the two ways a sortie ends on the ground: a landing or a crash.

import {
  GRAVITY, THROTTLE_RATE, PITCH_RATE, ROLL_RATE, YAW_RATE, PITCH_LIMIT,
  SPEED_MIN, SPEED_MAX, SPEED_THRUST, DRAG, LIFT_PITCH, FUEL_FULL, FUEL_BURN,
  DAMAGE_MAX, CEILING, STEP,
} from './config.js';
import { groundHeight, isWater } from './terrain.js';

export const EVENT_LANDED = 'landed';
export const EVENT_CRASH = 'crash';
export const EVENT_RING = 'ring';

/** Heading angle in radians, wrapped to [0, 2PI). */
function wrap(a) { a %= Math.PI * 2; return a < 0 ? a + Math.PI * 2 : a; }

export function createAircraft(start) {
  return {
    x: start.x, z: start.z, alt: start.alt,
    heading: start.heading, pitch: 0, roll: 0,
    speed: start.speed, vspeed: 0,
    throttle: 0.65,
    fuel: FUEL_FULL, damage: 0,
    engineCeilingFade: 1,
    onGround: false, crashed: false, landed: false,
    stall: false, overspeed: false,
    gearUp: false, // gear is down on the ground and on takeoff runs
  };
}

/**
 * Integrate one fixed step. `events` collects {type, ...} this step produced.
 * Controls: axis pitch/roll/yaw in [-1, 1], throttleDir -1|0|1.
 */
export function advance(plane, input, dt = STEP, events = []) {
  if (plane.crashed || plane.landed) return;

  // --- controls ---
  plane.throttle = Math.min(1, Math.max(0, plane.throttle + input.throttle(1) * THROTTLE_RATE * dt - input.throttle(-1) * THROTTLE_RATE * dt));
  const authority = clamp(plane.speed / 40, 0.25, 1.4); // dead controls when slow
  const elev = clamp(input.axis('pitch'), -1, 1);
  const ail = clamp(input.axis('roll'), -1, 1);
  const rud = clamp(input.axis('yaw'), -1, 1);
  plane.pitch = clamp(plane.pitch - elev * PITCH_RATE * authority * dt, -PITCH_LIMIT, PITCH_LIMIT);
  plane.roll += ail * ROLL_RATE * authority * dt;
  plane.roll = clamp(plane.roll, -Math.PI, Math.PI);
  plane.roll *= Math.pow(0.25, dt); // wings level themselves slowly
  plane.heading = wrap(plane.heading + rud * YAW_RATE * dt - Math.sin(plane.roll) * 0.55 * authority * dt);

  // --- engine and speed ---
  plane.engineCeilingFade = clamp(1 - Math.max(0, plane.alt - CEILING) / 800, 0.25, 1);
  let thrust = plane.throttle * (plane.fuel > 0 ? 1 : 0.15) * plane.engineCeilingFade;
  const target = SPEED_THRUST * thrust + 8;
  plane.speed += ((target - plane.speed) * DRAG - GRAVITY * Math.sin(plane.pitch) * 0.35) * dt;
  plane.speed = Math.max(0, plane.speed);

  // --- lift and climb ---
  plane.stall = plane.speed < SPEED_MIN && !plane.onGround;
  const lift = clamp(plane.speed / 40, 0, 1.6) * Math.cos(plane.roll * 1.2);
  const climb = Math.sin(plane.pitch) * LIFT_PITCH * lift - GRAVITY * (1 - lift * 0.9);
  plane.vspeed = plane.vspeed * 0.5 + climb * 0.5;

  // --- move ---
  plane.x += Math.sin(plane.heading) * plane.speed * dt;
  plane.z += Math.cos(plane.heading) * plane.speed * dt;
  plane.alt += plane.vspeed * dt;

  // --- fuel and damage ---
  plane.fuel = Math.max(0, plane.fuel - FUEL_BURN * (0.35 + plane.throttle) * dt);
  plane.overspeed = plane.speed > SPEED_MAX;
  if (plane.overspeed) plane.damage += 6 * dt;
  if (plane.stall && plane.alt - groundHeight(plane.x, plane.z) < 60) plane.damage += 4 * dt;
  if (plane.damage >= DAMAGE_MAX) crash(plane, 'structural failure', events);

  // --- ground contact ---
  const ground = groundHeight(plane.x, plane.z);
  const height = plane.alt - ground;
  if (height <= 2) {
    const sink = -plane.vspeed;
    const slope = groundSlope(plane.x, plane.z);
    const flat = isWater(plane.x, plane.z);
    const overRunway = onRunway(plane.x, plane.z);
    if (flat || sink > 10 || Math.abs(plane.roll) > 0.5 || plane.speed > SPEED_MAX) {
      crash(plane, flat ? 'ditched in the sea' : 'hit the ground hard', events);
      plane.alt = ground + 2;
      return;
    }
    if (overRunway && sink < 4.5 && Math.abs(plane.pitch) < 0.25 && plane.speed < 75) {
      // wheels on tarmac: roll out
      plane.onGround = true;
      plane.alt = ground + 2;
      plane.vspeed = 0;
      plane.pitch *= 0.5;
      plane.roll *= 0.5;
      plane.speed = Math.max(0, plane.speed - 14 * dt - plane.throttle * 0);
      if (plane.speed < 2) {
        plane.landed = true;
        events.push({ type: EVENT_LANDED });
      }
      return;
    }
    if (!overRunway) {
      crash(plane, 'belly landing off the field', events);
      plane.alt = ground + 2;
      return;
    }
    // too fast / too steep on the runway: bounce, take damage
    plane.damage += sink * 4;
    plane.vspeed = Math.abs(sink) * 0.4 + 3;
    if (plane.damage >= DAMAGE_MAX) crash(plane, 'wrecked on touchdown', events);
  } else {
    plane.onGround = false;
  }
}

function groundSlope(x, z) {
  const d = 8;
  const h = groundHeight(x, z);
  return Math.max(Math.abs(groundHeight(x + d, z) - h), Math.abs(groundHeight(x, z + d) - h)) / d;
}

export function onRunway(x, z) {
  const rw = { x: 0, z: 0, len: 640, width: 46 };
  return Math.abs(x - rw.x) < rw.width / 2 + 8 && Math.abs(z - rw.z) < rw.len / 2 + 8;
}

export function crash(plane, cause, events) {
  if (plane.crashed) return;
