function drawClouds(ctx, camera, plane, w, h, focal) {
  const puffs = [
    [1200, 760, -800, 190], [-2000, 620, 600, 240], [3400, 900, 1800, 300],
    [-900, 1050, 2600, 260], [2600, 700, -2600, 220],
