    ctx.beginPath();
    ctx.arc(p.x + rad * 0.7, p.y + rad * 0.18, rad * 0.72, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(p.x - rad * 0.68, p.y + rad * 0.2, rad * 0.65, 0, Math.PI * 2);
    ctx.fill();
  }
