function drawRunway(ctx, camera, w, h, focal) {
  const rw = RUNWAY;
  const strip = [
    [rw.x - rw.width, rw.z - rw.len / 2 - 60],
    [rw.x + rw.width, rw.z - rw.len / 2 - 60],
    [rw.x + rw.width, rw.z + rw.len / 2 + 60],
    [rw.x - rw.width, rw.z + rw.len / 2 + 60],
